import os

def is_gp(arr):
    """Check if array is a geometric progression."""
    n = len(arr)
    if n <= 2:
        return True

    # Count zeros at the beginning
    leading_zeros = 0
    for i in range(n):
        if arr[i] == 0:
            leading_zeros += 1
        else:
            break

    if leading_zeros == n:
        return True

    # Find the first non-zero element
    first_nonzero_idx = leading_zeros
    if first_nonzero_idx == n:
        return True

    first_val = arr[first_nonzero_idx]
    second_val = arr[first_nonzero_idx + 1]

    if second_val == 0 and first_val != 0:
        return False

    if first_val == 0 and second_val != 0:
        return False

    if first_val == 0 and second_val == 0:
        # Check if all subsequent elements are 0
        for i in range(first_nonzero_idx + 1, n):
            if arr[i] != 0:
                return False
        return True

    # Determine the ratio r as a fraction to avoid float issues
    # Use cross-multiplication: arr[i+1] * arr[i] should equal arr[i+2] * arr[i+1]
    # But we need to handle the ratio properly

    # Simple approach: store ratios as cross-multiplication check
    # For sequence a, b, c: b/a = c/b => b*b = a*c

    # Check first ratio
    r_num, r_den = second_val, first_val if first_val != 0 else (1, 0)  # ratio as fraction

    # Actually, let's just use the cross-product method
    for i in range(n - 2):
        a, b, c = arr[i], arr[i+1], arr[i+2]
        if b == 0 and a == 0 and c != 0:
            return False
        if a == 0 and b != 0:
            return False
        if a != 0 and b == 0 and c == 0:
            return False
        # b/a = c/b  => b*b = a*c (when a, b are both non-zero)
        if a != 0 and b != 0:
            if b * b != a * c:
                return False

    return True

def check_gp(arr):
    """Helper to check GP with proper cross-multiplication."""
    n = len(arr)
    if n <= 2:
        return True

    # All zeros
    if all(x == 0 for x in arr):
        return True

    # Find first non-zero
    first_nonzero = next((i for i, x in enumerate(arr) if x != 0), -1)

    if first_nonzero == -1:
        # All zeros
        return True

    # Check from first non-zero onwards
    start_idx = first_nonzero + 1
    if start_idx >= n:
        return True

    a = arr[start_idx]
    b = arr[start_idx + 1]
    c = arr[start_idx + 2]

    if c == 0 and b == 0 and a == 0:
        return True

    # For sequence a, b, c to be GP (a, b, c non-zero), we need b/a = c/b => b*b = a*c
    # But we need to be careful about zeros

    for i in range(start_idx, n - 2):
        a_prev = arr[i]
        b_prev = arr[i+1]
        c_prev = arr[i+2]

        if a_prev == 0 and b_prev == 0 and c_prev == 0:
            continue

        if a_prev == 0:
            if b_prev == 0 and c_prev == 0:
                continue
            return False  # Can't have nonzero after zero unless all zeros

        if b_prev != 0:
            # Ratio b_prev / a_prev should equal c_prev / b_prev
            # => b_prev * b_prev = a_prev * c_prev
            if b_prev * b_prev != a_prev * c_prev:
                return False

    return True


