def solution(input_str):
    from collections import defaultdict

    lines = input_str.strip().split('\n')
    if not lines or len(lines) < 2:
        return '0\n'

    try:
        n, m = map(int, lines[0].split())
        a = list(map(int, lines[1].split()))
    except:
        return '0\n'

    # Read good pairs
    pairs = []
    for i in range(2, min(len(lines), 2 + m)):
        parts = lines[i].split()
        if len(parts) >= 2:
            pairs.append((int(parts[0]), int(parts[1])))

    if not pairs or not a:
        return '0\n'

    # Adjust indices to 0-based
    pairs = [(p[0] - 1, p[1] - 1) for p in pairs]

    # Function to get prime factorization
    def get_prime_factors(num):
        factors = defaultdict(int)
        d = 2
        temp = num
        while d * d <= temp:
            while temp % d == 0:
                factors[d] += 1
                temp //= d
            d += 1
        if temp > 1:
            factors[temp] += 1
        return dict(factors)

    # Count prime factors at even vs odd 1-based positions
    even_pos_factors = defaultdict(int)
    odd_pos_factors = defaultdict(int)

    for idx in range(n):
        one_based = idx + 1
        if one_based % 2 == 0:
            # Even position (1-based)
            for p, c in get_prime_factors(a[idx]).items():
                even_pos_factors[p] += c
        else:
            # Odd position (1-based)
            for p, c in get_prime_factors(a[idx]).items():
                odd_pos_factors[p] += c

    # Count matching prime factors across even/odd positions
    total_ops = 0
    all_primes = set(even_pos_factors.keys()) | set(odd_pos_factors.keys())
    for p in all_primes:
        total_ops += min(even_pos_factors.get(p, 0), odd_pos_factors.get(p, 0))

    return f"{total_ops}\n"

