            parts = list(map(int, lines[2 + i].split()))
            u, v, w = parts[0], parts[1], parts[2]
            edge_id = i + 1
            edges.append({'u': u, 'v': v, 'w': w, 'id': edge_id})
            adj[u].append((v, edge_id))
            adj[v].append((u, edge_id))

        def can_reach(start, target, blocked_edges):
            visited = set([start])
            queue = deque([start])
            while queue:
                curr = queue.popleft()
                if curr == target:
                    return True
                for nxt, eid in adj[curr]:
                    if eid not in blocked_edges and nxt not in visited:
                        visited.add(nxt)
                        queue.append(nxt)
            return False

