    lines = input_str.strip().split('\n')
    n = int(lines[0])
    a = list(map(int, lines[1].strip().split()))

    total = sum(a)

    if total <= 1:
        return "-1\n"

    # Find all divisors of total
    divisors = []
    i = 2
    while i * i <= total:
        if total % i == 0:
            divisors.append(i)
            if i * i != total:
                divisors.append(total // i)
        i += 1

    min_cost = float('inf')

    for k in divisors:
        cost = 0
        prefix_mod = 0
        for x in a:
            prefix_mod = (prefix_mod + x) % k
            cost += prefix_mod
