    """Check if there's a diagonal square of side k at center (r, c)."""
    n, m = len(matrix), len(matrix[0])

    if k < 2:
        return False

    if r - k < 0 or r + k >= n or c - k < 0 or c + k >= m:
        return False

    # For diagonal square of side k at center (r, c), border is at Manhattan distance k
    # Border cells: (r-k, c), (r+k, c), (r, c-k), (r, c+k) plus the 4 positions connecting them

    border_cells = set()
    border_cells.add((r - k, c))  # Left
    border_cells.add((r + k, c))  # Right
    border_cells.add((r, c - k))  # Top
    border_cells.add((r, c + k))  # Bottom

    # For larger k, add intermediate border cells
    for step in range(1, k):
        border_cells.add((r - step, c + step))  # Top-right edge
        border_cells.add((r + step, c + step))  # Bottom-right edge
        border_cells.add((r + step, c - step))  # Bottom-left edge
        border_cells.add((r - step, c - step))  # Top-left edge

    # Check all border cells are 1
    for (bi, bj) in border_cells:
        if matrix[bi][bj] != '1':
