def solution(s):
    n, l, r = map(int, s.split())

    if n == 1:
        return str(r - l + 1) + '\n'
    elif n == 2:
        return str((r - l + 1) * (r - l)) + '\n'
    else:
        import math
        from math import gcd

        count = 0
        max_q = int(math.isqrt(r))

        for q in range(2, max_q + 1):
            q_power = q ** (n - 1)
            if q_power > r:
                break

            for p in range(1, q):
                if gcd(p, q) != 1:
                    continue

                p_power = p ** (n - 1)

                # min_k: smallest k where last term >= l
                # max_k: largest k where first term <= r
                min_k = (l + p_power - 1) // p_power
                max_k = r // q_power

                if max_k >= min_k:
                    count += (max_k - min_k + 1)

        # Double for ratios > 1 (reciprocals)
        return str(count * 2) + '\n'

