def find_solution(nums, k):
    """Find a sequence of operations to reduce nums to a single value of 1."""
    ops = []

    def backtrack(current_nums):
        if len(current_nums) == 1:
            return current_nums[0] == 1

        n = len(current_nums)
        for i in range(n):
            for j in range(i + 1, n):
                new_val = f(current_nums[i] + current_nums[j], k)
                # Create new list by removing indices i and j and adding new_val
                new_nums = current_nums[:i] + current_nums[i+1:j] + current_nums[j+1:] + [new_val]

                if backtrack(new_nums):
                    ops.append((current_nums[i], current_nums[j]))
                    return True

        return False

    if backtrack(nums):
        return ops
    return None

