    import sys
    lines = input_str.strip().split('\n')
    n, r = int(lines[0].split()[0]), int(lines[0].split()[1])

    # Generate all valid integer points in circle of radius r
    points = []
    for x in range(-r, r + 1):
        for y in range(-r, r + 1):
            if x*x + y*y <= r*r:
                points.append((x, y))

    # If no points available or r <= 0
    if not points:
        return "0\n" + "\n".join("0 0" for _ in range(n))

    ans = 0
    best_positions = [[] for _ in range(n)]

    if len(points) >= n:
        # Strategy: Try placing all towers at distinct points first
        import itertools

        for perm in itertools.permutations(points[:min(n, len(points))], n):
            total = 0
            for i in range(n):
                for j in range(i+1, n):
                    dx = perm[i][0] - perm[j][0]
                    dy = perm[i][1] - perm[j][1]
                    total += dx*dx + dy*dy
            if total > ans:
                ans = total

                # Decode back to individual tower positions
                best_positions = list(perm)
    elif len(points) > 1:
        # Use at most len(points) different positions
        num_points = min(len(points), n)

        # Try groups of 2 positions (splits k and n-k towers)
        for i in range(num_points):
            for j in range(i+1, num_points):
