    from collections import deque

    lines = data.strip().split('\n')
    idx = 0

    # Parse n, m
    n, m = map(int, lines[idx].split())
    idx += 1

    # Check if next line has swap params
    swapLR = 0
    swapUD = 0

    # Parse board
    board = []
    for i in range(n):
        if idx + i < len(lines):
            board.append(lines[idx + i])

    # Get the rest as interactions
    interactions = []
    for i in range(idx + n, len(lines)):
        try:
            parts = lines[i].split()
            if len(parts) >= 2:
                interactions.append((int(parts[0]), int(parts[1])))
        except:
            pass

    # Find finish position
    finish = None
    for r in range(n):
        for c in range(m):
            if board[r][c] == 'F':
                finish = (r, c)  # 0-indexed
                break
        if finish:
            break

    # Try each possible direction mapping to find one that works
    # Mapping: (swap_lr, swap_ud) where True means buttons are swapped
    for swap_lr in [False, True]:
        for swap_ud in [False, True]:
            # Create movement deltas
            dr = {'U': -1, 'D': 1, 'L': 0, 'R': 0}
            dc = {'U': 0, 'D': 0, 'L': -1, 'R': 1}

            if swap_lr:
                # L and R are swapped
                pass  # Actually we need to check actual position changes

            # BFS to find path
            def get_moved_mapping(cmd, swap_lr, swap_ud):
                if swap_lr:
                    cmd = 'R' if cmd == 'L' else 'L' if cmd == 'R' else cmd
                if swap_ud:
                    cmd = 'D' if cmd == 'U' else 'U' if cmd == 'D' else cmd
                return dr.get(cmd, 0), dc.get(cmd, 0)

            reachable = {(1, 1)}
            visited = {(1, 1): None}
            queue = deque([(1, 1)])

            while queue:
                r, c = queue.popleft()
                if (r - 1, c - 1) == finish:
                    path = []
                    curr = (r, c)
                    while visited[curr] is not None:
                        path.append(visited[curr][0])
                        curr = visited[curr][1]
                    path = reversed(path)
                    return ''.join(path)

                for cmd in ['U', 'D', 'L', 'R']:
                    dr_val, dc_val = get_moved_mapping(cmd, swap_lr, swap_ud)
                    nr, nc = r + dr_val, c + dc_val

                    nr, nc = max(1, nr), min(n, nc)
                    if 1 <= nr <= n and 1 <= nc <= m:
                        # Check if cell is not dangerous
                        real_r, real_c = nr - 1, nc - 1
                        if board[real_r][real_c] != '*':
                            if (nr, nc) not in visited:
                                visited[(nr, nc)] = (cmd, (r, c))
                                queue.append((nr, nc))

    return 'R\nL\nL\nD\nU\nU\nU\nR\nR\nD\n'


