def solution(input_str):
    lines = input_str.strip().split('\n')
    if len(lines) < 2:
        return "NO\n"

    n = int(lines[0])

    def parse_coords():
        points = []
        idx = 1
        for i in range(n + 1):
            if idx >= len(lines):
                return None
            parts = lines[idx].split()
            if len(parts) < 3:
                idx += 1
                continue
            x, y, z = map(int, parts[:3])
            points.append((x, y, z))
            idx += 1
        return points

    def parse_line(idx):
        if idx >= len(lines):
            return None
        return lines[idx].split()

    vertices = parse_coords()
    if vertices is None or len(vertices) < 2:
        return "NO\n"

    idx = len(vertices)
    parts = parse_line(idx)
    if parts is None or len(parts) < 2:
        return "NO\n"

    vp, vs = int(parts[0]), int(parts[1])

    idx += 1
    starting_part = parse_line(idx)
    if starting_part is None or len(starting_part) < 3:
        return "NO\n"

    hp_pos = tuple(int(p) for p in starting_part)

    def dist_sq(p1, p2):
        return (p1[0] - p2[0])**2 + (p1[1] - p2[1])**2 + **(p1[2] - p2[2])2

    def dist(p1, p2):
        return math.sqrt(dist_sq(p1, p2))

    segment_dists = []
    segment_times = []

    for i in range(len(vertices) - 1):
        d = dist(vertices[i], vertices[i+1])
        segment_dists.append(d)
        segment_times.append(d / vs)

    elapsed = 0.0
    best_time = None
    best_pos = None

    for seg_idx in range(len(vertices) - 1):
        start_v = vertices[seg_idx]
        end_v = vertices[seg_idx + 1]
        seg_dist = segment_dists[seg_idx]
        seg_dur = segment_times[seg_idx]
        seg_start_time = elapsed

        if seg_dist <= 1e-9:
            elapsed += seg_dur
            continue

        dist_hp_start = dist(hp_pos, start_v)

        if dist_hp_start * 1e0 >= seg_dur * vp + 1e-9:
            elapsed += seg_dur
            continue

        search_start = seg_start_time
        search_end = seg_start_time + seg_dur

        def can_reach(t):
            t_remaining = t - search_start
            if t_remaining < -1e-9:
                return False
            t_remaining = max(0.0, t_remaining)
            hp_dist = vp * t_remaining
            snitch_dist_in_seg = vs * t_remaining
            if snitch_dist_in_seg > seg_dist + 1e-9:
                snitch_dist_in_seg = seg_dist

            catch_point = start_v[0] + (end_v[0] - start_v[0]) * (snitch_dist_in_seg / seg_dist), \
                          start_v[1] + (end_v[1] - start_v[1]) * (snitch_dist_in_seg / seg_dist), \
                          start_v[2] + (end_v[2] - start_v[2]) * (snitch_dist_in_seg / seg_dist)

            from catch_point to hp_pos
            dist_needed = dist(hp_pos, catch_point)

            return dist_needed <= hp_dist + 1e-9

        if can_reach(search_start):
            best_time = search_start

        if can_reach(search_end):
            if search_end < best_time or best_time is None:
                best_time = search_end

        for _ in range(100):
            if best_time is None:
                break
            mid = (search_start + search_end) / 2
            if can_reach(mid):
                if (search_end - search_start) < 1e-12:
                    break
                midpoint = (search_start + search_end) / 2
                if can_reach(midpoint):
                    best_time = midpoint
                    search_end = midpoint
                else:
                    search_start = mid
            else:
                best_time = None
                search_start = mid if search_end > search_start else mid

        if best_time is not None:
            snitch_dist = vs * (best_time - seg_start_time)
            if snitch_dist < 0:
                snitch_dist = 0
            if snitch_dist > seg_dist:
                snitch_dist = seg_dist

            progress = snitch_dist / seg_dist
            catch_v = (
                start_v[0] + (end_v[0] - start_v[0]) * progress,
                start_v[1] + (end_v[1] - start_v[1]) * progress,
                start_v[2] + (end_v[2] - start_v[2]) * progress
            )
            best_pos = (catch_v[0], catch_v[1], catch_v[2])

        elapsed += seg_dur

    if best_time is None:
        return "NO\n"

    return f"YES\n{best_time:.10f}\n{best_pos[0]:.10f} {best_pos[1]:.10f} {best_pos[2]:.10f}\n"

