def count_independent_sets(n, edges):
    if n == 0:
        return 1

    adj = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    n1 = n // 2
    # Split vertices: 1..n1 in A, (n1+1)..n in B

    # Step 1: For each subset of A, check independence and compute neighbors in B
    # Store in freq array of size 2^(n-n1)

    num_B = n - n1
    freq = [0] * (1 << num_B)

    # Vertices in A: 1 to n1
    # Vertices in B: n1+1 to n
    # We'll use 0-indexed internally for B mapping

    # For each subset of A
    adj_list = [[] for _ in range(n + 1)]
    for u, v in edges:
        adj_list[u].append(v)
        adj_list[v].append(u)

    # Generate subsets of A
    for mask in range(1 << n1):
        independent = True
        # Check if this subset of A is independent
        # For each u in S_A, check that no neighbor of u is also in S_A
        for i in range(n1):
            if not ((mask >> i) & 1):
                continue
            u = i + 1  # vertex index
            for v in adj_list[u]:
                if (v <= n1):  # neighbor in A
                    v_idx = v - 1
                    if (mask >> v_idx) & 1:
                        independent = False
                        break
            if not independent:
                break

        if independent:
            # Compute neighbors in B
            b_mask = 0
            for i in range(n1):
                if (mask >> i) & 1:
                    u = i + 1
                    for v in adj_list[u]:
                        if v > n1:
                            b_idx = v - n1 - 1
                            b_mask |= (1 << b_idx)
            freq[b_mask] += 1

    # SOS compute: sum_freq[mask] = sum_{sub ⊆ mask} freq[sub]
    sum_freq = list(freq)
    for i in range(num_B):
        for mask in range(1 << num_B):
            if mask & (1 << i):
                sum_freq[mask] += sum_freq[mask ^ (1 << i)]

    # Step 2: For each subset of B, check independence and compute neighbors in A
    # If independent, add sum_freq[neighbors_complement] to ans

    ans = 0
    # Vertices in B: n1+1 to n, map to 0..num_B-1

    for mask in range(1 << num_B):
        independent = True
        # Check if subset of B is independent
        for i in range(num_B):
            if not ((mask >> i) & 1):
                continue
            v = i + n1 + 1  # vertex index in original graph
            neighbors_in_A = set(adj_list[v])
            for u in adj_list[v]:
                if u <= n1:
                    if (mask >> (u - 1)) & 1:
                        independent = False
                        break
            if not independent:
                break

        if independent:
            # Compute neighbors in A for this S_B
            a_neighbors = 0
            for i in range(num_B):
                if (mask >> i) & 1:
                    v = i + n1 + 1
                    for u in adj_list[v]:
                        if u <= n1:
                            a_neighbors |= (1 << (u - 1))

            # We need a_neighbors & S_A = ∅ for all valid S_A
            # Valid S_A have neighbors_in_B & S_B = ∅, equivalently
            # We want to count S_A with independent property where
            # neighbors_in_B(S_A) & mask B == 0
            # neighbors_in_B(S_A) is exactly what sums to sum_freq[mask] for those
            # Wait no. We sum freq[m] where m & mask == 0.
            # The SOS gives sum_freq[M] = sum_{sub ⊆ M} freq[sub]
            # So we need sum_freq[~mask & all_B]

            valid_B_mask = ((1 << num_B) - 1) ^ mask
            ans += sum_freq[valid_B_mask]

    return ans

