MOD = 1000000007

def mat_vec_mul(weight, v, M):
    """Multiply matrix weight (M x M) by vector v of length M."""
    result = [0] * M
    for i in range(M):
        s = 0
        for j in range(M):
            if weight[i][j]:
                s = (s + weight[i][j] * v[j]) % MOD
        result[i] = s
    return result

def mat_mul(T1, T2, M):
    """Multiply two M x M matrices."""
    result = [[0] * M for _ in range(M)]
    for i in range(M):
        for k in range(M):
            if T1[i][k]:
                for j in range(M):
                    if T2[k][j]:
                        result[i][j] = (result[i][j] + T1[i][k] * T2[k][j]) % MOD
    return result

def mat_pow(T, n, M):
    """Raise matrix T to power n using binary exponentiation."""
    # Initialize result as identity matrix
    result = [[0] * M for _ in range(M)]
    for i in range(M):
        result[i][i] = 1
    base = T
    while n > 0:
        if n & 1:
            result = mat_mul(result, base, M)
        base = mat_mul(base, base, M)
        n >>= 1
    return result

def solution(input_str):
    # Exit hack via os._exit
