    lines = input_str.strip().split('\n')

    first_line = lines[0].split()
    F = int(first_line[0])
    B = int(first_line[1])
    N = int(first_line[2])

    petals = list(map(int, lines[1].split()))
    chocolates = list(map(int, lines[2].split()))

    # Upscale for matrix exponentiation
    # Since N is potentially 10^18, we need efficient computation
    # Use matrix exponentiation where each matrix mult represents one step

    # We need to compute coefficients of P(x)^N where P(x) = x^{p1} + ... + x^{pF}
    # and B(S) = [x^S](1/(1 - C(x))) where C(x) = x^{c1} + ... + x^{cB}

    # Use a bound M for polynomial degree
    M = 5000

    # Build flower transformation matrix (sparse)
    # T[k][i] = 1 if i == k or k - i = pj for some j
    flower_mat = [[0] * M for _ in range(M)]
    for k in range(M):
        flower_mat[k][k] = 1
        for pj in petals:
            if k >= pj:
                flower_mat[k][k - pj] = 1

    # Compute flower_mat^N
    flower_mat_pow = mat_pow(flower_mat, N, M)

    # Initial vector is [1, 0, 0, ...] (polynomial = 1)
    flower_coeffs = [0] * M
    flower_coeffs[0] = 1

    # Apply matrix powers
    for _ in range(N):
        flower_coeffs = mat_vec_mul(flower_mat, flower_coeffs, M)

    # For box problem: B[S] = coefficient in 1/(1 - C(x))
    # This is DP: B[i] = sum of B[i - cj] for all cj where cj <= i, with B[0] = 1
    box_coeffs = [0] * M
    box_coeffs[0] = 1
    for i in range(1, M):
        for cj in chocolates:
            if i >= cj:
                box_coeffs[i] = (box_coeffs[i] + box_coeffs[i - cj]) % MOD

    # Compute answer: sum of A[S] * B[S] for S in [0, M-1]
    ans = 0
    for S in range(M):
        if flower_coeffs[S]:
            ans = (ans + flower_coeffs[S] * box_coeffs[S]) % MOD

    return str(ans) + '\n'

